"use client";

/**
 * TokscaleMark — the brand mark rebuilt as square dither cells.
 *
 * The mark's three blades (public/assets/hero-logo.svg, 131×25 viewBox) are
 * sampled on a 14-row grid; each cell at or above half coverage becomes one
 * square cell of the accent, drawn with a one-cell gap so the mark reads as
 * dither cells even where they touch. Pure and deterministic, so the same
 * cells render on the server and in tests — no canvas, no hydration flash.
 */

/** Mark blade polygons in the 131×25 logo viewBox. */
const BLADES: [number, number][][] = [
  [
    [10.6965, 7.31864],
    [10.6965, 24.7708],
    [14.6373, 11.2594],
  ],
  [
    [10.6965, 7.31864],
    [28.1486, 7.31864],
    [14.6373, 11.2594],
  ],
  [
    [10.6965, 3.37783],
    [10.6965, 7.31864],
    [3.37783, 6.1927],
    [0, 0],
  ],
];

const MARK_WIDTH = 28.1486;
const MARK_HEIGHT = 24.7708;
const ROWS = 14;

function inside(blade: [number, number][], x: number, y: number): boolean {
  let hit = false;
  for (let i = 0, j = blade.length - 1; i < blade.length; j = i++) {
    const [xi, yi] = blade[i];
    const [xj, yj] = blade[j];
    if (yi > y !== yj > y && x < ((xj - xi) * (y - yi)) / (yj - yi) + xi) hit = !hit;
  }
  return hit;
}

/** Coverage of cell (col, row), from an 8×8 supersample. */
function cellCoverage(col: number, row: number, scale: number): number {
  const SAMPLES = 8;
  let hit = 0;
  for (let sy = 0; sy < SAMPLES; sy++) {
    for (let sx = 0; sx < SAMPLES; sx++) {
      const x = (col + (sx + 0.5) / SAMPLES) / scale;
      const y = (row + (sy + 0.5) / SAMPLES) / scale;
      if (BLADES.some((blade) => inside(blade, x, y))) hit++;
    }
  }
  return hit / (SAMPLES * SAMPLES);
}

const CELL = 2;
/** Edges are kept, not rounded away: the blades are thinner than a cell. */
const COVERAGE = 0.2;
const SCALE = ROWS / MARK_HEIGHT;
const COLS = Math.ceil(MARK_WIDTH * SCALE);
const MARK_VIEW_WIDTH = COLS * CELL;
const MARK_VIEW_HEIGHT = ROWS * CELL;

const CELLS: [number, number][] = (() => {
  const cells: [number, number][] = [];
  for (let row = 0; row < ROWS; row++) {
    for (let col = 0; col < COLS; col++) {
      if (cellCoverage(col, row, SCALE) >= COVERAGE) cells.push([col, row]);
    }
  }
  return cells;
})();

export function TokscaleMark({ className, height = 28 }: { className?: string; height?: number }) {
  const width = (height / MARK_VIEW_HEIGHT) * MARK_VIEW_WIDTH;
  return (
    <svg
      aria-hidden="true"
      className={className}
      width={width}
      height={height}
      viewBox={`0 0 ${MARK_VIEW_WIDTH} ${MARK_VIEW_HEIGHT}`}
      fill="var(--v2-accent)"
    >
      {CELLS.map(([col, row]) => (
        <rect key={`${col}-${row}`} x={col * CELL} y={row * CELL} width={CELL} height={CELL} />
      ))}
    </svg>
  );
}

