/**
 * The letters alone, in a box trimmed to their bounds (x 31.666–130.054,
 * y 7.178–25 in the shared 131×25 viewBox), so the box centre is the optical
 * centre of the word.
 */
export function TokscaleWordmark({ className, height = 20 }: { className?: string; height?: number }) {
  const width = (height / 17.822) * 98.388;
  return (
    <svg
      aria-hidden="true"
      className={className}
      width={width}
      height={height}
      viewBox="31.666 7.17822 98.388 17.82178"
      fill="var(--v2-text)"
    >
      <path d={TOKSCALE_WORDMARK_PATH} />
    </svg>
  );
}
